import SwiftUI
import AppKit
import AVKit
import Metal
import LUACore

let luaBlue=Color(red:0.48,green:0.66,blue:1)
let luaSurface=Color(red:0.13,green:0.14,blue:0.17)
struct Card<Content:View>:View {
 @ViewBuilder var content:Content
 var body:some View{VStack(alignment:.leading,spacing:14){content}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(luaSurface,in:RoundedRectangle(cornerRadius:18)).overlay(RoundedRectangle(cornerRadius:18).stroke(Color.white.opacity(0.09),lineWidth:1))}
}
struct Metric:View {
 var name:String,value:String,caption:String="",color:Color = .white
 var body:some View{VStack(alignment:.leading,spacing:5){Text(name).font(.caption).foregroundStyle(.secondary);Text(value).font(.system(size:25,weight:.semibold,design:.rounded)).foregroundStyle(color);if !caption.isEmpty{Text(caption).font(.caption2).foregroundStyle(.secondary)}}.frame(maxWidth:.infinity,alignment:.leading)}
}
struct Chart:View {
 let values:[Double]
 var body:some View{GeometryReader{g in Path{p in for (i,v) in values.enumerated(){let point=CGPoint(x:Double(i)*g.size.width/Double(max(1,values.count-1)),y:g.size.height*(1-min(100,max(0,v))/100));if i==0{p.move(to:point)}else{p.addLine(to:point)}}}.stroke(luaBlue,style:StrokeStyle(lineWidth:1.6,lineCap:.round,lineJoin:.round))}.frame(height:40).accessibilityLabel("Histórico de uso da CPU")}
}
struct LuaRoot:View {
 @ObservedObject var model:Model
 @State var compact=false
 var body:some View{
  HStack(spacing:0){if !compact{sidebar};VStack(spacing:0){HStack(spacing:12){Text(model.page.rawValue).font(.system(size:22,weight:.semibold,design:.rounded));Spacer();if model.update != nil{Button("Atualizar"){Task{await model.downloadUpdate()}}.tint(luaBlue).buttonStyle(.borderedProminent).disabled(model.updateBusy)};Button{model.openOverlay?()}label:{Image(systemName:"rectangle.on.rectangle")}.help("Abrir sobreposição");Button{compact.toggle()}label:{Image(systemName:compact ? "sidebar.left":"rectangle.compress.vertical")}.help("Alternar tamanho")}.padding(22)
    ScrollView{LuaPage(model:model,page:model.page).padding(.horizontal,22).padding(.bottom,20)}
    HStack{Image(systemName:"moon.stars.fill").foregroundStyle(luaBlue);Text("LUA \(Model.version) · macOS Beta");Spacer();if compact{Menu{ForEach(Page.allCases){page in Button(page.rawValue){model.page=page}}}label:{Image(systemName:"square.grid.2x2")}}}.font(.caption).foregroundStyle(.secondary).padding(14)
   }.frame(minWidth:380)
  }.background(Color(red:0.075,green:0.08,blue:0.1)).foregroundStyle(.white).preferredColorScheme(.dark)
  .overlay(alignment:.bottom){if !model.notice.isEmpty{HStack{Image(systemName:"moon.fill").foregroundStyle(luaBlue);Text(model.notice).font(.callout);Spacer();Button{model.notice=""}label:{Image(systemName:"xmark")}}.padding(14).background(.ultraThinMaterial,in:RoundedRectangle(cornerRadius:14)).padding(18).shadow(radius:12)}}
 }
 var sidebar:some View{VStack(alignment:.leading,spacing:4){HStack(spacing:10){Image(systemName:"moon.stars.fill").font(.system(size:29)).foregroundStyle(luaBlue);VStack(alignment:.leading){Text("LUA").font(.system(size:24,weight:.bold,design:.rounded));Text("Seu Mac, no seu ritmo").font(.caption2).foregroundStyle(.secondary)}}.padding(.bottom,24).padding(.top,12)
  ForEach(Page.allCases){p in Button{model.page=p}label:{HStack(spacing:12){Image(systemName:p.icon).frame(width:20);Text(p.rawValue);Spacer()}.font(.system(size:13,weight:model.page==p ? .semibold:.regular)).padding(.vertical,10).padding(.horizontal,12).background(model.page==p ? luaBlue.opacity(0.16):.clear,in:RoundedRectangle(cornerRadius:10)).foregroundStyle(model.page==p ? luaBlue:.secondary)}.buttonStyle(.plain)};Spacer();Text("NATIVO PARA macOS").font(.system(size:9,weight:.medium)).tracking(2).foregroundStyle(.secondary)}.padding(16).frame(width:205).background(Color.white.opacity(0.025))}
}
