   HStack{Button("Galeria"){model.page = .gallery}.frame(maxWidth:.infinity);Button("Analisar Mac"){model.page = .analysis}.frame(maxWidth:.infinity)}
  }}
 var hardware:some View{VStack(spacing:16){Card{HStack{Metric(name:"CPU",value:LuaFormat.percent(model.cpu));Metric(name:"RAM",value:LuaFormat.percent(Double(model.ramUsed)*100/Double(max(1,model.ramTotal))))};Chart(values:model.cpuHistory);Text("Memória ativa, cabeada e comprimida. A definição difere da leitura de RAM do Windows.").font(.caption).foregroundStyle(.secondary)};Card{Text("GPU e sensores").font(.headline);Text(MTLCreateSystemDefaultDevice()?.name ?? "GPU indisponível");Text("Estado térmico: \(model.thermalText)");Text("Temperatura em °C, ventoinhas e uso percentual da GPU: sem uma API pública compatível garantida nesta edição. O LUA não inventa leituras.").font(.callout).foregroundStyle(.secondary);Text("CPU e memória coletadas pelas APIs Mach do macOS.").font(.caption).foregroundStyle(luaBlue)}}}
 var network:some View{VStack(spacing:16){Card{Text("Tráfego atual").font(.headline);HStack{Metric(name:"↓ Recebimento",value:LuaFormat.rate(model.down),color:.cyan);Metric(name:"↑ Envio",value:LuaFormat.rate(model.up),color:luaBlue)};Text("Interfaces físicas en* (Wi-Fi/Ethernet). VPNs virtuais são excluídas para evitar contagem duplicada.").font(.caption).foregroundStyle(.secondary)};Card{Text("Teste de conexão").font(.headline);Text("Usa 10 MB no download e 2 MB no upload, com a Cloudflare. Latência HTTPS, não ping ICMP.").font(.callout).foregroundStyle(.secondary);Button(model.speedBusy ? "Medindo…":"Testar internet"){model.speed()}.disabled(model.speedBusy);if !model.speedResult.isEmpty{Text(model.speedResult).foregroundStyle(luaBlue).textSelection(.enabled)}}}}
