  if !(page == .cleanup ? model.duplicates:model.entries).isEmpty{Card{HStack{Button("Marcar tudo"){model.selected=Set((page == .cleanup ? model.duplicates:model.entries).map{$0.id})};Button("Desmarcar"){model.selected=[]};Spacer();Button("Enviar à Lixeira"){model.trashSelected()}.tint(.red).disabled(model.selected.isEmpty)};ForEach(Array((page == .cleanup ? model.duplicates:model.entries).prefix(250))){item in HStack{Toggle(isOn:Binding(get:{model.selected.contains(item.id)},set:{if $0{model.selected.insert(item.id)}else{model.selected.remove(item.id)}})){VStack(alignment:.leading){Text(item.url.lastPathComponent).lineLimit(1);Text(item.url.deletingLastPathComponent().path).font(.caption2).foregroundStyle(.secondary).lineLimit(1)}};Spacer();Text(LuaFormat.bytes(item.bytes)).font(.caption);Button{NSWorkspace.shared.activateFileViewerSelecting([item.url])}label:{Image(systemName:"folder")}}};if (page == .cleanup ? model.duplicates:model.entries).count>250{Text("Primeiros 250 itens exibidos. Marcar tudo inclui todos os resultados.").font(.caption).foregroundStyle(.secondary)}}}
