 var analysis:some View{VStack(spacing:16){Card{Text("Diagnóstico local").font(.headline);Text(model.report()).font(.system(.callout,design:.monospaced)).textSelection(.enabled);Button("Exportar relatório"){model.exportReport()}};Card{Text("Sugestões").font(.headline);Text(model.free<15_000_000_000 ? "Pouco espaço livre: revise arquivos grandes e duplicados antes de enviar à Lixeira.":"Espaço livre disponível. Revise periodicamente capturas e arquivos grandes.");Text(model.cpu>85 ? "Uso alto da CPU: confira aplicativos em execução.":"Observe o histórico da CPU durante tarefas pesadas.");Text("Leituras não substituem diagnóstico físico do hardware.").font(.caption).foregroundStyle(.secondary)}}}
 var settings:some View{VStack(spacing:16){Card{Text("Sobreposição").font(.headline);Text("Janelas móveis e fixáveis, com cliques através fora da edição. Digitar habilita foco para pesquisas.").foregroundStyle(.secondary);Picker("Atalho",selection:$model.shortcut){ForEach(["⌃ Espaço","⌘⇧ Espaço","⌥⇧ Espaço"],id:\.self){Text($0)}}.onChange(of:model.shortcut){_,_ in model.save();model.updateShortcuts?()};Text("⌃ Espaço pode conflitar com a troca de idioma do macOS; escolha outra combinação se necessário.").font(.caption).foregroundStyle(.secondary);Button("Abrir sobreposição"){model.openOverlay?()}};Card{Text("Privacidade e captura").font(.headline);Text("Capturas ficam na pasta escolhida. O histórico temporário fica em Application Support/LUA. Monitoramento e limpeza são locais.").foregroundStyle(.secondary);Button("Abrir permissões de gravação"){NSWorkspace.shared.open(URL(string:"x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture")!)};Button("Mostrar pasta de capturas"){NSWorkspace.shared.open(model.folder)}};Card{Text("LUA \(Model.version) · macOS Beta").font(.headline);Text("macOS 15 ou posterior · Apple Silicon e Intel");Text("APIs nativas: SwiftUI, AppKit, Mach, ScreenCaptureKit, AVFoundation e Metal. Sem drivers do Windows.").font(.caption).foregroundStyle(.secondary);Button("Verificar atualizações"){Task{await model.checkUpdates()}};if let update=model.update{Button("Baixar \(update.version)"){Task{await model.downloadUpdate()}}.disabled(model.updateBusy)};Toggle("Baixar atualizações automaticamente",isOn:$model.autoUpdates).onChange(of:model.autoUpdates){_,_ in model.save()};Text("O download é verificado por tamanho e SHA-256. Instalação exige substituir LUA.app em Aplicativos. Nesta beta, não há assinatura Developer ID nem notarização da Apple.").font(.caption).foregroundStyle(.secondary);Link("Repositório e informações ↗",destination:URL(string:"https://github.com/onekaer/lua-")!)}}}
