struct CaptureActions:View {
 @ObservedObject var model:Model
 var body:some View{HStack(spacing:10){action("Print","camera.viewfinder",.white){model.screenshot()};Menu{ForEach([30,60,120],id:\.self){seconds in Button("Salvar \(seconds) s"){model.clipSeconds=seconds;model.clip()}}}label:{VStack(spacing:8){Image(systemName:"gobackward").font(.system(size:21));Text("\(model.clipSeconds) s").font(.caption)}.frame(maxWidth:.infinity).frame(height:65)}.menuStyle(.borderlessButton).padding(.horizontal,12).background(luaBlue.opacity(0.1),in:RoundedRectangle(cornerRadius:12)).disabled(!model.captureActive||model.clipBusy);action(model.isRecording ? "Parar":"Gravar",model.isRecording ? "stop.fill":"circle.fill",.pink){model.toggleRecording()}}}
 func action(_ title:String,_ symbol:String,_ color:Color,_ block:@escaping()->Void)->some View{Button(action:block){VStack(spacing:8){Image(systemName:symbol).font(.system(size:21));Text(title).font(.caption)}.frame(maxWidth:.infinity).frame(height:65).foregroundStyle(color)}.buttonStyle(.plain).background(color.opacity(0.08),in:RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(color.opacity(0.15)))}
}
struct MediaThumb:View {
 let item:Media
 @State var image:NSImage?
 var body:some View{ZStack{Color.black.opacity(0.2);if let image{Image(nsImage:image).resizable().scaledToFit()}else{Image(systemName:item.kind=="Prints" ? "photo":"play.rectangle").font(.largeTitle).foregroundStyle(luaBlue)}}.task(id:item.id){if item.kind=="Prints"{image=NSImage(contentsOf:item.url)}else{let generator=AVAssetImageGenerator(asset:AVURLAsset(url:item.url));generator.appliesPreferredTrackTransform=true;generator.maximumSize=CGSize(width:440,height:250);if let result=try? await generator.image(at:.zero){image=NSImage(cgImage:result.image,size:.zero)}}}}
}
